columns: DataTableColumn<RoleRow>[] = [
    {
      key: 'role',
      header: '역할',
      width: "var(--qd-atelier-width-fc89e844ea)",
      render: (r) => (
        <div>
          <div style={{ fontSize: QDScale.font[13], color: T.text }}>{r.label}</div>
          <div style={{ fontSize: QDScale.font[12], color: T.subtle, lineHeight: QDScale.leading.snug }}>{product === 'q-atelier' ? r.use : OTHER_PRODUCT_USE}</div>
        </div>
      ),
    },
    {
      key: 'current',
      header: '지금 모델',
      width: "var(--qd-atelier-width-4a8e5e3bb8)",
      render: (r) => (
        <div>
          <div style={{ fontSize: QDScale.font[13] }}>{optionOf(r, r.current)?.label ?? r.current}</div>
          <div style={{ fontSize: QDScale.font[12], color: r.source === 'default' ? T.muted : T.subtle }}>
            {SOURCE_TEXT[r.source]}
            {r.source === 'screen' && r.updatedAt ? ` · ${when(r.updatedAt)}` : ''}
          </div>
          {!r.keyAvailable && <div style={{ fontSize: QDScale.font[12], color: T.red }}>이 회사 키가 서버에 없습니다</div>}
        </div>
      ),
    },
    {
      key: 'price',
      header: '단가(100만 토큰)',
      width: "var(--qd-atelier-width-051abb7ab4)",
      render: (r) => (
        <span style={{ fontSize: QDScale.font[12], fontFamily: QDScale.family.mono, color: T.subtle }}>{priceText(optionOf(r, r.current))}</span>
      ),
    },
    {
      key: 'act',
      width: "var(--qd-atelier-width-91269935bd)",
      align: 'right',
      render: (r) => <TextAction onClick={() => startEdit(r)}>바꾸기</TextAction>,
    },
  ]

columns: DataTableColumn<Row>[] = [
    { key: 'raw', header: '낱말 · 대상', width: "var(--qd-atelier-width-b66da02177)", render: (r) => (
      <div>
        <div style={{ fontSize: QDScale.font[13] }}>{r.raw}</div>
        <div style={{ fontSize: QDScale.font[12], color: T.subtle, fontFamily: QDScale.family.mono }}>{r.target} · {r.seen_count}번 · {r.last_seen_at.slice(0, 10)}</div>
      </div>
    ) },
    { key: 'votes', header: '세 회사 답', width: "var(--qd-atelier-width-edb4cac963)", render: (r) => r.votes.length === 0 ? (
      <span style={{ fontSize: QDScale.font[12], color: T.muted }}>답 없음(키 없음 · 시간 초과)</span>
    ) : (
      <div style={{ fontSize: QDScale.font[12], lineHeight: QDScale.leading.snug }}>
        {r.votes.map((v) => (
          <div key={v.provider}>
            <Tag color={T.muted}>{PROVIDER_KR[v.provider]}</Tag>{' '}
            <span style={{ fontFamily: QDScale.family.mono }}>{v.canonical ?? '모름'}</span>
            <span style={{ color: T.subtle }}> · {CONFIDENCE_KR[v.confidence]} · {v.rationale}</span>
          </div>
        ))}
      </div>
    ) },
    { key: 'decide', header: '표준 유형', width: "var(--qd-atelier-width-b66da02177)", render: (r) => r.status === 'pending' ? (
      <select
        className="qa-input"
        aria-label={`${r.raw} 의 표준 유형`}
        value={choice[r.id] ?? ''}
        onChange={(e) => setChoice((c) => ({ ...c, [r.id]: e.target.value }))}
        style={{ width: "var(--qd-atelier-width-b7aa1ec004)", fontSize: QDScale.font[13], padding: `${QDScale.space[1]} ${QDScale.space[2]}` }}
      >
        <option value="">고르십시오</option>
        {r.candidates.map((c) => <option key={c} value={c}>{c}</option>)}
      </select>
    ) : (
      <div style={{ fontSize: QDScale.font[12] }}>
        <Tag color={r.status === 'aliased' ? T.green : T.muted}>{FILTER_KR[r.status]}</Tag>
        {r.aliasLine && <div style={{ fontFamily: QDScale.family.mono, marginTop: QDScale.space[1] }}>{r.aliasLine}</div>}
        {r.note && <div style={{ color: T.subtle, marginTop: QDScale.space[1] }}>{r.note}</div>}
      </div>
    ) },
    { key: 'act', width: "var(--qd-atelier-width-e104eb5fa2)", align: 'right', render: (r) => r.status === 'pending' ? (
      <div style={{ display: 'flex', gap: QDScale.space[2], justifyContent: 'flex-end', alignItems: 'center' }}>
        <TextAction onClick={() => void decide(r, 'rejected')} disabled={busy === r.id}>안 씀</TextAction>
        <Btn sm onClick={() => void decide(r, 'aliased')} pending={busy === r.id}>별칭으로 정하고 복사</Btn>
      </div>
    ) : (
      <div style={{ display: 'flex', gap: QDScale.space[2], justifyContent: 'flex-end', alignItems: 'center' }}>
        {r.aliasLine && <TextAction onClick={() => void copyAndTell(r.aliasLine ?? '')}>줄 복사</TextAction>}
        <TextAction onClick={() => void decide(r, 'reopen')} disabled={busy === r.id}>다시 대기로</TextAction>
      </div>
    ) },
  ]

columns: DataTableColumn<SeededTemplate>[] = [
    {
      key: 'code',
      header: '문서 코드',
      width: "var(--qd-atelier-width-dc9eac3f89)",
      render: (row) => (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: QDScale.space[1], minWidth: "var(--qd-atelier-min-width-f24a3b2189)" }}>
          <span style={{ fontFamily: QDScale.family.mono, color: T.champagne, fontSize: QDScale.font[12], overflowWrap: 'anywhere' }}>{row.doc_type}</span>
          {docsetTag(row)}
        </div>
      ),
    },
    {
      key: 'name',
      header: '양식명',
      width: "var(--qd-atelier-width-48abb035bf)",
      render: (row) => <span style={{ color: T.text, fontFamily: QDScale.family.ui, overflowWrap: 'anywhere' }}>{row.name}</span>,
    },
    { key: 'state', header: '상태', width: "var(--qd-atelier-width-433b187c26)", render: (row) => fileTag(row) },
    {
      key: 'date',
      header: '갱신일',
      width: "var(--qd-atelier-width-7080f70fb4)",
      render: (row) => <span style={{ fontSize: QDScale.font[12], color: T.muted, fontFamily: QDScale.family.mono }}>{shortDate(row.updated_at)}</span>,
    },
    {
      key: 'act',
      header: '동작',
      width: "var(--qd-atelier-width-aebc026e77)",
      render: (row) => <div style={{ display: 'flex', gap: QDScale.space[1.5], flexWrap: 'wrap', alignItems: 'center' }}>{rowActions(row)}</div>,
    },
  ]

columns: DataTableColumn<{ entry: LeaderboardEntry; idx: number }>[] = [
    {
      key: '순위',
      header: '순위',
      align: 'left',
      render: ({ idx }) => (
        <span style={{ fontFamily: QDScale.family.mono, color: T.muted, fontSize: QDScale.font[12] }}>#{idx + 1}</span>
      ),
    },
    {
      key: '전문가',
      header: '전문가',
      align: 'left',
      render: ({ entry }) => (
        <>
          <div style={{ color: T.text, fontWeight: "var(--qd-font-weight-medium)" }}>{entry.name ?? '-'}</div>
          <div style={{ fontSize: QDScale.font[12], color: T.muted, fontFamily: QDScale.family.mono }}>{entry.email}</div>
          {entry.organization && (
            <div style={{ fontSize: QDScale.font[12], color: T.muted }}>{entry.organization}</div>
          )}
        </>
      ),
    },
    {
      key: '전문분야',
      header: '전문분야',
      align: 'left',
      render: ({ entry }) =>
        entry.specialty ? (
          <Tag color={T.champagne}>{specialtyLabel(entry.specialty)}</Tag>
        ) : (
          <span style={{ color: T.muted }}>-</span>
        ),
    },
    {
      key: '평가건수',
      header: '평가건수',
      align: 'left',
      render: ({ entry }) => (
        <span style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.subtle }}>
          {entry.evaluated_count} / {entry.review_count}
        </span>
      ),
    },
    scoreCol('종합', (e) => e.avg_overall),
    scoreCol('전문성', (e) => e.avg_professionalism),
    scoreCol('신속성', (e) => e.avg_speed),
    scoreCol('명료성', (e) => e.avg_clarity),
    scoreCol('실용성', (e) => e.avg_practicality),
  ]

records.value:
{
                  a.planned_at ? (
                    <span style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.subtle, letterSpacing: "var(--qd-atelier-letter-spacing-0d0739d0da)" }}>
                      {a.planned_at}
                    </span>
                  ) : undefined
                }

{
                  a.agreement_expiry && a.status === 'active' ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: shown.expired ? T.red : soon ? T.warning : T.subtle, fontWeight: shown.expired || soon ? "var(--qd-font-weight-semibold)" : "var(--qd-font-weight-normal)" }}>
                      계약 {dday !== null && dday < 0 ? `만료 ${-dday}일` : `D-${dday}`}
                    </span>
                  ) : undefined
                }

{
                <span style={{ display: 'inline-flex', flexDirection: 'column', alignItems: 'flex-end', gap: QDScale.space[0.5] }}>
                  <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: c.owner_id ? T.subtle : T.warning }}>
                    담당 {c.owner_id ? ownerName.get(c.owner_id) || '-' : '미지정'}
                  </span>
                  <span
                    style={{
                      fontFamily: QDScale.family.ui,
                      fontSize: QDScale.font[12],
                      color: isOverdue ? T.red : T.subtle,
                      fontWeight: isOverdue ? "var(--qd-font-weight-semibold)" : "var(--qd-font-weight-normal)",
                    }}
                  >
                    {!c.due_date
                      ? '기한 없음'
                      : isOverdue && due !== null
                        ? `${Math.abs(due)}일 초과`
                        : due === 0
                          ? '오늘'
                          : `D-${due}`}
                  </span>
                </span>
              }

{
                  z.next_monitoring_due && z.status !== 'out_of_use' ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: ddColor, textAlign: 'right' }}>
                      모니터링 {daysLeft !== null && daysLeft < 0 ? `지연 ${-daysLeft}일` : `D-${daysLeft}`}
                    </span>
                  ) : undefined
                }

{
                  c.next_update_due ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: dday !== null && dday <= 90 ? T.red : T.subtle }}>
                      갱신 {dday !== null && dday < 0 ? `초과 ${-dday}일` : `D-${dday}`}
                    </span>
                  ) : undefined
                }

{[
              {
                key: 'need',
                header: '사용자 요구',
                width: "var(--qd-atelier-width-48abb035bf)",
                render: (r) =>
                  r.need ? (
                    <div style={{ maxWidth: "var(--qd-atelier-max-width-2de5c532d5)" }}>
                      <div style={{ color: T.champagne, fontFamily: QDScale.family.mono, fontSize: QDScale.font[12] }}>{r.need.ref_id}</div>
                      <div style={{ color: T.subtle, fontSize: QDScale.font[12] }}>{r.need.body}</div>
                    </div>
                  ) : (
                    <span style={{ color: T.muted, fontSize: QDScale.font[12] }}>-</span>
                  ),
              },
              {
                key: 'input',
                header: '설계입력',
                width: "var(--qd-atelier-width-48abb035bf)",
                render: (r) =>
                  r.input ? (
                    <div style={{ maxWidth: "var(--qd-atelier-max-width-dd354b257a)" }}>
                      <div style={{ color: T.champagne, fontFamily: QDScale.family.mono, fontSize: QDScale.font[12] }}>{r.input.ref_id}</div>
                      <div style={{ color: T.text, fontSize: QDScale.font[12], fontWeight: "var(--qd-font-weight-medium)" }}>{r.input.body}</div>
                      {!r.input.verifiable && (
                        <div style={{ color: T.warning, fontSize: QDScale.font[12], marginTop: QDScale.space[0.5] }}>검증 방법 미기재</div>
                      )}
                    </div>
                  ) : (
                    <span style={{ color: T.warning, fontSize: QDScale.font[12] }}>등록부 미연결</span>
                  ),
              },
              {
                key: 'output',
                header: '설계출력',
                width: "var(--qd-atelier-width-48abb035bf)",
                render: (r) => (
                  <div style={{ color: T.subtle, maxWidth: "var(--qd-atelier-max-width-50b3f3d072)" }}>
                    {r.trace?.output_id && (
                      <div style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.champagne }}>{r.trace.output_id}</div>
                    )}
                    {r.trace?.output_artifact && <div style={{ fontSize: QDScale.font[12] }}>{r.trace.output_artifact}</div>}
                    {!r.trace?.output_id && !r.trace?.output_artifact && (
                      <span style={{ color: T.red, fontSize: QDScale.font[12] }}>(없음)</span>
                    )}
                  </div>
                ),
              },
              {
                key: 'verif',
                header: '검증',
                width: "var(--qd-atelier-width-48abb035bf)",
                render: (r) => {
                  if (!r.trace) return <span style={{ color: T.red, fontSize: QDScale.font[12] }}>(없음)</span>;
                  const t = r.trace;
                  const st = (t.verification_status ?? 'pending') as 'pending' | 'pass' | 'fail';
                  return (
                    <div>
                      {t.verification_id && (
                        <div style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.champagne, marginBottom: QDScale.space[0.5] }}>{t.verification_id}</div>
                      )}
                      <div className="qa-trace-status-controls">
                        {(['pending', 'pass', 'fail'] as const).map((sv) => {
                          const M = VV_META[sv];
                          const Icon = M.icon;
                          return (
                            <ChoiceChip
                              key={sv}
                              on={st === sv}
                              color={M.color}
                              ariaLabel={M.label}
                              title={M.label}
                              onClick={() => void updateStatus(t.id, 'verification_status', sv)}
                            >
                              <Icon size={ICON.sizeXs} strokeWidth={ICON.strokeWidth} aria-hidden="true" />
                            </ChoiceChip>
                          );
                        })}
                      </div>
                    </div>
                  );
                },
              },
              {
                key: 'valid',
                header: '유효성확인',
                width: "var(--qd-atelier-width-48abb035bf)",
                render: (r) => {
                  if (!r.trace) return <span style={{ color: T.red, fontSize: QDScale.font[12] }}>(없음)</span>;
                  const t = r.trace;
                  const st = (t.validation_status ?? 'pending') as 'pending' | 'pass' | 'fail';
                  return (
                    <div>
                      {t.validation_id && (
                        <div style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.champagne, marginBottom: QDScale.space[0.5] }}>{t.validation_id}</div>
                      )}
                      <div className="qa-trace-status-controls">
                        {(['pending', 'pass', 'fail'] as const).map((sv) => {
                          const M = VV_META[sv];
                          const Icon = M.icon;
                          return (
                            <ChoiceChip
                              key={sv}
                              on={st === sv}
                              color={M.color}
                              ariaLabel={M.label}
                              title={M.label}
                              onClick={() => void updateStatus(t.id, 'validation_status', sv)}
                            >
                              <Icon size={ICON.sizeXs} strokeWidth={ICON.strokeWidth} aria-hidden="true" />
                            </ChoiceChip>
                          );
                        })}
                      </div>
                    </div>
                  );
                },
              },
              {
                key: 'state',
                header: '상태',
                width: "var(--qd-atelier-width-d9bdf1127d)",
                render: (r) => <GapBadges gaps={r.gaps} />,
              },
              {
                key: 'actions',
                width: "var(--qd-atelier-width-d68e58999b)",
                render: (r) => {
                  if (!canWrite) return null;
                  // 매트릭스에 아직 안 올라온 설계입력 → 여기서 바로 올린다.
                  if (!r.trace) {
                    return (
                      <TextAction onClick={() => setAdding(r)}>
                        <Plus size={ICON.sizeXs} strokeWidth={ICON.strokeWidth} aria-hidden="true" />
                        연결
                      </TextAction>
                    );
                  }
                  const traceId = r.trace.id;
                  return (
                    <div className="qa-trace-row-actions">
                    <TextAction onClick={() => openDetail(r)}>세부</TextAction>
                    <Btn p={false} sm danger onClick={() => void deleteRow(traceId)} ariaLabel="삭제">
                      <Trash2 size={ICON.sizeXs} strokeWidth={ICON.strokeWidth} aria-hidden="true" />
                    </Btn>
                    </div>
                  );
                },
              },
            ]}

{
                  a.expiry_date ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: T.subtle }}>
                      만료 {a.expiry_date}
                    </span>
                  ) : undefined
                }

{
                  t.status === 'certified' && t.certificate_expiry ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: dday !== null && dday <= 180 ? T.red : T.subtle }}>
                      인증 {dday !== null && dday < 0 ? `만료 ${-dday}일` : `D-${dday}`}
                    </span>
                  ) : undefined
                }

{
                  a.expiry_date ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: T.subtle }}>만료 {a.expiry_date}</span>
                  ) : undefined
                }

{
                  a.conducted_at ? (
                    <span style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.subtle, letterSpacing: "var(--qd-atelier-letter-spacing-0d0739d0da)" }}>
                      {a.conducted_at.slice(0, 10)}
                    </span>
                  ) : undefined
                }

{
                  a.next_report_due ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: T.subtle }}>
                      차기 {a.next_report_due}
                    </span>
                  ) : undefined
                }

{
                  s.next_review_due && s.status !== 'superseded' ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: ddColor, textAlign: 'right' }}>
                      검토 {daysLeft !== null && daysLeft < 0 ? `지연 ${-daysLeft}일` : `D-${daysLeft}`}
                    </span>
                  ) : undefined
                }

{
                  a.next_revalidation_date && a.status === 'validated' ? (
                    <span style={{ fontFamily: QDScale.family.ui, fontSize: QDScale.font[12], color: dday !== null && dday <= REVAL_WARN_DAYS ? T.red : T.subtle }}>
                      재밸리데이션 {dday !== null && dday < 0 ? `초과 ${-dday}일` : `D-${dday}`}
                    </span>
                  ) : undefined
                }

{
                  showDday ? (
                    <span
                      style={{
                        fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], fontWeight: "var(--qd-font-weight-semibold)", letterSpacing: "var(--qd-atelier-letter-spacing-0d0739d0da)",
                        color: urgent || (dday !== null && dday < 0) ? T.red : T.subtle,
                      }}
                    >
                      {dday !== null && dday < 0 ? `초과 ${-dday}일` : `D-${dday}`}
                    </span>
                  ) : a.status === 'closed' ? (
                    <CheckCircle2 size={QDPresentation.iconSize[16]} color={T.green} aria-hidden="true" />
                  ) : undefined
                }

{[
              {
                key: 'cr_number',
                header: 'CR 번호',
                width: "var(--qd-atelier-width-5a5f7abe41)",
                render: (cr) => (
                  <span style={{ fontFamily: QDScale.family.mono, color: T.champagne, fontSize: QDScale.font[12], fontWeight: "var(--qd-font-weight-semibold)" }}>
                    <GitPullRequest size={QDPresentation.iconSize[11]} style={{ display: 'inline', marginRight: QDScale.space[1], verticalAlign: 'middle' }} />
                    {cr.cr_number}
                  </span>
                ),
              },
              {
                key: 'title',
                header: '제목 / 사유',
                width: "var(--qd-atelier-width-2edb6baa63)",
                render: (cr) => (
                  <div style={{ minWidth: "var(--qd-atelier-min-width-f24a3b2189)", overflow: 'hidden' }}>
                    <div
                      style={{
                        whiteSpace: 'nowrap',
                        textOverflow: 'ellipsis',
                        overflow: 'hidden',
                        fontFamily: QDScale.family.serif,
                        fontWeight: "var(--qd-font-weight-medium)",
                      }}
                    >
                      {cr.title}
                    </div>
                    <div
                      style={{
                        fontSize: QDScale.font[12],
                        color: T.muted,
                        fontFamily: QDScale.family.mono,
                        marginTop: QDScale.space[0.5],
                        whiteSpace: 'nowrap',
                        textOverflow: 'ellipsis',
                        overflow: 'hidden',
                      }}
                    >
                      {cr.reason}
                    </div>
                  </div>
                ),
              },
              {
                key: 'project',
                header: '프로젝트',
                width: "var(--qd-atelier-width-ffcb6e42ab)",
                render: (cr) => (
                  <span
                    style={{
                      fontSize: QDScale.font[12],
                      color: T.subtle,
                      fontFamily: QDScale.family.serif,
                      whiteSpace: 'nowrap',
                      textOverflow: 'ellipsis',
                      overflow: 'hidden',
                    }}
                    title={cr.project?.title ?? ''}
                  >
                    {cr.project ? (
                      <>
                        <span style={{ color: T.muted, fontFamily: QDScale.family.mono, fontSize: QDScale.font[12] }}>
                          {cr.project.code}
                        </span>
                        <br />
                        {cr.project.title}
                      </>
                    ) : (
                      <span style={{ color: T.muted }}>-</span>
                    )}
                  </span>
                ),
              },
              {
                key: 'target_doc',
                header: '대상 문서',
