function orgSubColumns(tierColor: Record<string, string>): DataTableColumn<OrgSubRow>[] {
  return [
    {
      key: 'org',
      header: '조직',
      width: '1fr',
      render: (row) => {
        const s = orgSubRowState(row);
        return (
          <div style={{ display: 'flex', alignItems: 'center', gap: QDScale.space[2], overflow: 'hidden' }}>
            {(s.isOverQuota || s.isExpired) && <span style={{ color: T.red, fontSize: QDScale.font[12] }}>●</span>}
            {!s.isOverQuota && !s.isExpired && (s.isNearQuota || s.isExpiringSoon) && (
              <span style={{ color: T.warning, fontSize: QDScale.font[12] }}>●</span>
            )}
            <span
              style={{
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
                fontWeight: "var(--qd-font-weight-medium)",
              }}
            >
              {row.org_name}
            </span>
          </div>
        );
      },
    },
    {
      key: 'plan',
      header: '플랜',
      width: 'var(--qd-atelier-org-table-plan-width)',
      // 요금제 표기를 한 벌로 (화면 검토 A29 · 2026-09-27)
      render: (row) => <Tag color={tierColor[row.tier] ?? T.muted}>{subscriptionPlanLabel(row.tier)}</Tag>,
    },
    {
      key: 'usage',
      header: '월 사용량 / 한도',
      width: 'var(--qd-atelier-org-table-usage-track)',
      render: (row) => {
        const s = orgSubRowState(row);
        return (
          <div>
            <div
              style={{
                fontSize: QDScale.font[12],
                fontFamily: QDScale.family.mono,
                color: s.usageColor,
                marginBottom: "var(--qd-atelier-margin-bottom-9378f643b6)",
                fontWeight: s.isOverQuota || s.isNearQuota ? "var(--qd-font-weight-semibold)" : "var(--qd-font-weight-normal)",
              }}
            >
              {row.usage_count.toLocaleString()} / {row.monthly_quota.toLocaleString()}
              <span style={{ color: T.muted, marginLeft: QDScale.space[1.5], fontWeight: "var(--qd-font-weight-normal)" }}>
                ({row.usage_pct.toFixed(1)}%)
              </span>
            </div>
            <div style={{ height: "var(--qd-atelier-height-8fa4d4e302)", background: T.surface2, borderRadius: "var(--qd-atelier-border-radius-8b5bf1ec3e)", overflow: 'hidden' }}>
              <div
                style={{
                  width: `${Math.min(row.usage_pct, 100)}%`,
                  height: "var(--qd-atelier-height-26ecbf76a0)",
                  background: s.usageColor,
                }}
              />
            </div>
          </div>
        );
      },
    },
    {
      key: 'status',
      header: '상태',
      width: 'var(--qd-atelier-org-table-plan-width)',
      render: (row) => (
        <Tag color={row.status === 'active' ? T.green : T.red}>{SUBSCRIPTION_STATUS_LABEL[row.status] ?? row.status}</Tag>
      ),
    },
    {
      key: 'expiry',
      header: '만료',
      width: 'var(--qd-atelier-org-table-expiry-width)',
      align: 'right',
      render: (row) => {
        const s = orgSubRowState(row);
        return (
          <div
            style={{
              textAlign: 'right',
              fontFamily: QDScale.family.mono,
              fontSize: QDScale.font[12],
              color: s.expiryColor,
              fontWeight: s.isExpired || s.isExpiringSoon ? "var(--qd-font-weight-semibold)" : "var(--qd-font-weight-normal)",
            }}
          >
            {s.isExpired
              ? `만료 ${Math.abs(row.expires_in_days)}일 전`
              : row.expires_in_days === 0
              ? '오늘 만료'
              : `D-${row.expires_in_days}`}
          </div>
        );
      },
    },
  ];
}

