                          fontFamily: QDScale.family.mono,
                          fontSize: QDScale.font[12],
                          textAlign: 'center',
                        }}
                      >
                        {k.product_code ?? '-'}
                      </span>
                    ),
                  },
                  {
                    key: 'decision_date',
                    width: "var(--qd-atelier-width-f47e3b970d)",
                    align: 'right',
                    render: (k) => (
                      <span
                        style={{
                          color: T.muted,
                          fontFamily: QDScale.family.mono,
                          fontSize: QDScale.font[12],
                          textAlign: 'right',
                        }}
                      >
                        {k.decision_date ?? '-'}
                      </span>
                    ),
                  },
                ]}

definitions.source:
procColumns: DataTableColumn<LibraryProc>[] = [
    {
      key: 'no',
      header: '번호',
      width: "var(--qd-atelier-width-d9e8188b2c)",
      render: (p) => <span style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.muted }}>{p.no}</span>,
    },
    {
      key: 'title',
      header: '문서',
      width: "var(--qd-atelier-width-48abb035bf)",
      render: (p) => (
        <div>
          <div style={{ color: T.text, fontFamily: QDScale.family.serif, fontWeight: p.kind === 'manual' ? "var(--qd-font-weight-semibold)" : "var(--qd-font-weight-normal)", overflowWrap: 'anywhere' }}>{p.title}</div>
          <div style={{ fontSize: QDScale.font[12], color: T.muted, fontFamily: QDScale.family.mono, marginTop: QDScale.space[0.5], overflowWrap: 'anywhere' }}>
            {p.iso}
            {p.covers ? ` · 통합: ${p.covers}` : ''}
          </div>
        </div>
      ),
    },
    {
      key: 'tag',
      header: '구분',
      width: "var(--qd-atelier-width-e5a3feb436)",
      render: (p) => (p.required ? <span style={{ fontSize: QDScale.font[12], color: T.muted }}>필수</span> : <Tag color={T.subtle}>{p.conditional ? '조건부' : '권장'}</Tag>),
    },
    {
      key: 'forms',
      header: '양식',
      width: "var(--qd-atelier-width-2d09dd5b97)",
      render: (p) =>
        p.formIds.length > 0 ? (
          <TextAction onClick={() => showFormsOf(p)} title="이 절차서가 받치는 양식만 아래에 모아 봅니다" label={`양식 ${p.formIds.length}종 보기: ${p.title}`}>
            {p.formIds.length}종 보기
          </TextAction>
        ) : (
          <span style={{ fontSize: QDScale.font[12], color: T.muted }}>-</span>
        ),
    },
    {
      key: 'act',
      width: "var(--qd-atelier-width-0f2aca65dd)",
      align: 'right',
      render: (p) => actions(p.id, p.title),
    },
  ]

formColumns: DataTableColumn<LibraryForm>[] = [
    {
      key: 'id',
      header: '번호',
      width: "var(--qd-atelier-width-2b524186b8)",
      render: (f) => <span style={{ fontFamily: QDScale.family.mono, fontSize: QDScale.font[12], color: T.muted }}>{f.id}</span>,
    },
    {
      key: 'title',
      header: '양식',
      width: "var(--qd-atelier-width-48abb035bf)",
      render: (f) => (
        <div>
          <div style={{ color: T.text, fontFamily: QDScale.family.serif, overflowWrap: 'anywhere' }}>{f.title}</div>
          {f.records.length > 0 && (
            <div style={{ fontSize: QDScale.font[12], color: T.muted, marginTop: QDScale.space[0.5], lineHeight: QDScale.leading.relaxed, overflowWrap: 'anywhere' }}>
              남기는 기록: {f.records.join(' · ')}
            </div>
          )}
          {f.products.length > 0 && (
            <div style={{ fontSize: QDScale.font[12], color: T.subtle, marginTop: QDScale.space[0.5], overflowWrap: 'anywhere' }}>
              제품 문서 「{productsLine(f.products)}」 의 빈 양식과 같습니다
            </div>
          )}
        </div>
      ),
    },
    {
      key: 'kind',
      header: '갈래',
      width: "var(--qd-atelier-width-2b524186b8)",
      render: (f) => <span style={{ fontSize: QDScale.font[12], color: T.muted }}>{KIND_LABEL[f.kind]}</span>,
    },
    {
      key: 'act',
      width: "var(--qd-atelier-width-0f2aca65dd)",
      align: 'right',
      render: (f) => actions(f.id, f.title),
    },
  ]
